sys_ux_client_script.script:
/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 * @param {any} params.imports
 */
function handler({api, event, helpers, imports}) {
    const eventName = event.name;
    var navigationPayload = {};

    if (eventName == 'NOW_RECORD_LIST_CONNECTED#ROW_CLICKED'){
        navigationPayload = {
            route: 'record',
            fields: {
                table: event.payload.recordTable == 'sn_grc_document' ? 'sn_compliance_authority_document' : event.payload.recordTable,
                sysId: event.payload.sys_id
            },
        };
    }else if (eventName == 'NOW_RECORD_LIST_CONNECTED#VIEW_ALL_CLICKED'){
        var query = '';
        if (event.payload.table == 'sn_compliance_m2m_statement_citation')
            query = api.data.control_side_panel.output.citationsQuery + '^GROUPBYsn_compliance_citation.document';
        else if(event.payload.table == 'sn_risk_risk')
            query = api.data.control_side_panel.output.relatedRisksQuery;

        navigationPayload = {
            route: 'list-view',
            fields: {
                table: event.payload.table,
            },
            params: {
                query: query,
                columns: event.payload.columns,
                listTitle: event.payload.listTitle
            },
            title: event.payload.listTitle,
        };
    }

    api.emit("NAV_ITEM_SELECTED", navigationPayload);
}
